package io.github.jesterportfolio.hearth.economy;

import java.util.*;import java.util.concurrent.*;import java.sql.*;
import io.github.jesterportfolio.hearth.persistence.*;

/** 기존 realm 잠금·발급 context를 사용한다. 보존된 원본/다른 realm을 수정하지 않는다. */
public final class PlatformStore {
    public record Preference(boolean enabled,Set<String> goods,long revision){public Preference{goods=Set.copyOf(goods);if(goods.size()>128||goods.stream().anyMatch(s->!s.matches("[a-z][a-z0-9_-]{0,63}")))throw new IllegalArgumentException("AUTOSELL_GOODS");}}
    public record Reset(UUID request,String role,long generation,UUID oldWorld,String key,long seed,String terrain,UUID world,double x,double y,double z,String phase){}
    private final PostgresProgressStore db;private final EconomyStore economy;private final UUID realm;
    public PlatformStore(PostgresProgressStore db,EconomyStore economy,UUID realm){this.db=db;this.economy=economy;this.realm=realm;}
    private static StorageFailure fail(String code){return new StorageFailure("platform",code);}
    private void lock(Connection c)throws Exception{economy.housingLock(c,economy.context(realm,new UUID(0,0)));}
    @FunctionalInterface private interface Work<T>{T run(Connection c)throws Exception;}
    private <T>CompletionStage<T> tx(String name,Work<T> work){return db.module(name,c->{c.setAutoCommit(false);try{lock(c);var out=work.run(c);c.commit();return out;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}});}
    public CompletionStage<Map<UUID,Preference>> preferences(){return tx("platform_preferences",c->{var out=new HashMap<UUID,Preference>();try(var s=c.prepareStatement("SELECT player_uuid,enabled,goods,revision FROM hearth_economy.platform_preference WHERE realm_id=?")){s.setObject(1,realm);try(var r=s.executeQuery()){while(r.next()){if(out.size()>=4096)throw fail("PLATFORM_CAPACITY");out.put(r.getObject(1,UUID.class),new Preference(r.getBoolean(2),Set.copyOf(Arrays.asList((String[])r.getArray(3).getArray())),r.getLong(4)));}}}return Map.copyOf(out);});}
    public CompletionStage<Preference> preference(ServerProgressAccess.Context ctx,Preference next,long expected){return tx("platform_preference",c->{economy.housingLock(c,ctx);if(!realm.equals(ctx.storyRunId()))throw fail("PLATFORM_SCOPE");try(var s=c.prepareStatement("INSERT INTO hearth_economy.platform_preference VALUES(?,?,?,?,0) ON CONFLICT(realm_id,player_uuid) DO UPDATE SET enabled=EXCLUDED.enabled,goods=EXCLUDED.goods,revision=hearth_economy.platform_preference.revision+1 WHERE hearth_economy.platform_preference.revision=? RETURNING revision")){s.setObject(1,realm);s.setObject(2,ctx.playerId());s.setBoolean(3,next.enabled);s.setArray(4,c.createArrayOf("text",new TreeSet<>(next.goods).toArray()));s.setLong(5,expected);try(var r=s.executeQuery()){if(!r.next()||expected< -1||expected>=0&&r.getLong(1)==0)throw fail("ECON_QUOTE_CHANGED");return new Preference(next.enabled,next.goods,r.getLong(1));}}});}
    private Reset read(ResultSet r)throws Exception{return new Reset(r.getObject("request_id",UUID.class),r.getString("role"),r.getLong("generation"),r.getObject("old_uuid",UUID.class),r.getString("new_key"),r.getLong("seed"),r.getString("terrain"),r.getObject("new_uuid",UUID.class),r.getDouble("entry_x"),r.getDouble("entry_y"),r.getDouble("entry_z"),r.getString("phase"));}
    private List<Reset> rows(Connection c)throws Exception{var out=new ArrayList<Reset>();try(var s=c.prepareStatement("SELECT * FROM hearth_economy.resource_reset WHERE realm_id=? ORDER BY generation,role")){s.setObject(1,realm);try(var r=s.executeQuery()){while(r.next()){if(out.size()>=4096)throw fail("PLATFORM_CAPACITY");out.add(read(r));}}}return List.copyOf(out);}
    public CompletionStage<List<Reset>> resets(){return tx("resource_reset_read",this::rows);}
    public CompletionStage<Reset> reserve(UUID request,String role,UUID old,long expected,long seed,String terrain){return tx("resource_reset_reserve",c->{if(!Set.of("wilderness","nether","novice","end").contains(role)||!Set.of("NORMAL","FLAT").contains(terrain)||expected<0||expected==Long.MAX_VALUE)throw fail("RESET_REQUEST");var existing=rows(c);var duplicate=existing.stream().filter(r->r.request.equals(request)).findFirst();if(duplicate.isPresent()){var d=duplicate.get();if(!d.role.equals(role)||!d.oldWorld.equals(old)||d.seed!=seed||!d.terrain.equals(terrain)||d.generation!=expected+1)throw fail("RESET_REQUEST_CONFLICT");return d;}var active=existing.stream().filter(r->r.role.equals(role)&&r.phase.equals("ACTIVE")).findFirst();if(active.map(Reset::generation).orElse(0L)!=expected||active.isPresent()&&!active.get().world.equals(old)||existing.stream().anyMatch(r->r.role.equals(role)&&Set.of("PREPARING","READY").contains(r.phase)))throw fail("RESET_CAS");long next=expected+1;String key="hearth_resource:r_"+role+"_"+request.toString().replace("-","");try(var s=c.prepareStatement("INSERT INTO hearth_economy.resource_reset(realm_id,request_id,role,generation,old_uuid,new_key,seed,terrain,phase) VALUES(?,?,?,?,?,?,?,?, 'PREPARING')")){s.setObject(1,realm);s.setObject(2,request);s.setString(3,role);s.setLong(4,next);s.setObject(5,old);s.setString(6,key);s.setLong(7,seed);s.setString(8,terrain);s.executeUpdate();}return new Reset(request,role,next,old,key,seed,terrain,null,0,0,0,"PREPARING");});}
    public CompletionStage<Reset> prepared(Reset intent,UUID world,double x,double y,double z){return tx("resource_reset_prepared",c->{if(world==null||!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z))throw fail("RESET_ENTRY");try(var s=c.prepareStatement("UPDATE hearth_economy.resource_reset SET new_uuid=?,entry_x=?,entry_y=?,entry_z=?,phase='READY' WHERE realm_id=? AND request_id=? AND phase='PREPARING' AND new_key=? AND old_uuid=? RETURNING *")){s.setObject(1,world);s.setDouble(2,x);s.setDouble(3,y);s.setDouble(4,z);s.setObject(5,realm);s.setObject(6,intent.request);s.setString(7,intent.key);s.setObject(8,intent.oldWorld);try(var r=s.executeQuery()){if(!r.next())throw fail("RESET_CAS");return read(r);}}});}
    public CompletionStage<Void> activate(Reset intent){return tx("resource_reset_activate",c->{var actual=rows(c).stream().filter(r->r.request.equals(intent.request)).findFirst().orElseThrow();if(!actual.equals(intent)||!actual.phase.equals("READY"))throw fail("RESET_CAS");try(var s=c.prepareStatement("UPDATE hearth_economy.resource_reset SET phase='RETIRED' WHERE realm_id=? AND role=? AND phase='ACTIVE'")){s.setObject(1,realm);s.setString(2,intent.role);s.executeUpdate();}try(var s=c.prepareStatement("UPDATE hearth_economy.resource_reset SET phase='ACTIVE' WHERE realm_id=? AND request_id=? AND phase='READY'")){s.setObject(1,realm);s.setObject(2,intent.request);if(s.executeUpdate()!=1)throw fail("RESET_CAS");}return null;});}
    public CompletionStage<Void> abort(UUID request){return tx("resource_reset_abort",c->{try(var s=c.prepareStatement("UPDATE hearth_economy.resource_reset SET phase='ABORTED' WHERE realm_id=? AND request_id=? AND phase IN ('PREPARING','READY')")){s.setObject(1,realm);s.setObject(2,request);if(s.executeUpdate()!=1)throw fail("RESET_CAS");}return null;});}
    public CompletionStage<Void> config(UUID request,String name,String before,String after,String from,String to){return tx("platform_config_change",c->{if(!before.matches("[a-f0-9]{64}")||!after.matches("[a-f0-9]{64}")||name.length()>128||!Set.of("PREPARED","COMMITTED","ROLLED_BACK").contains(to))throw fail("CONFIG_CHANGE");if(from==null){try(var q=c.prepareStatement("SELECT name,before_hash,after_hash FROM hearth_economy.platform_config_change WHERE realm_id=? AND request_id=?")){q.setObject(1,realm);q.setObject(2,request);try(var r=q.executeQuery()){if(r.next()){if(!name.equals(r.getString(1))||!before.equals(r.getString(2))||!after.equals(r.getString(3)))throw fail("CONFIG_REQUEST_CONFLICT");return null;}}}try(var s=c.prepareStatement("INSERT INTO hearth_economy.platform_config_change VALUES(?,?,?,?,?,'PREPARED',now())")){s.setObject(1,realm);s.setObject(2,request);s.setString(3,name);s.setString(4,before);s.setString(5,after);s.executeUpdate();}}else try(var s=c.prepareStatement("UPDATE hearth_economy.platform_config_change SET state=? WHERE realm_id=? AND request_id=? AND name=? AND before_hash=? AND after_hash=? AND state=?")){s.setString(1,to);s.setObject(2,realm);s.setObject(3,request);s.setString(4,name);s.setString(5,before);s.setString(6,after);s.setString(7,from);if(s.executeUpdate()!=1)throw fail("CONFIG_CAS");}return null;});}
    public CompletionStage<String> configState(UUID request){return tx("platform_config_state",c->{try(var s=c.prepareStatement("SELECT state FROM hearth_economy.platform_config_change WHERE realm_id=? AND request_id=?")){s.setObject(1,realm);s.setObject(2,request);try(var r=s.executeQuery()){if(!r.next())throw fail("CONFIG_MISSING");return r.getString(1);}}});}
    public CompletionStage<Void> requireInactive(){return tx("platform_disabled_guard",c->{for(String query:List.of("SELECT 1 FROM hearth_economy.resource_reset WHERE realm_id=? AND phase IN ('ACTIVE','PREPARING','READY') LIMIT 1","SELECT 1 FROM hearth_economy.platform_preference WHERE realm_id=? AND enabled LIMIT 1","SELECT 1 FROM hearth_economy.platform_config_change WHERE realm_id=? AND state='PREPARED' LIMIT 1"))try(var s=c.prepareStatement(query)){s.setObject(1,realm);try(var r=s.executeQuery()){if(r.next())throw fail("PLATFORM_RUNTIME_REQUIRED");}}return null;});}
    public CompletionStage<List<String>> configHistory(){return tx("platform_config_history",c->{var out=new ArrayList<String>();try(var s=c.prepareStatement("SELECT request_id,name,state FROM hearth_economy.platform_config_change WHERE realm_id=? ORDER BY created_at DESC LIMIT 20")){s.setObject(1,realm);try(var r=s.executeQuery()){while(r.next())out.add(r.getObject(1)+" "+r.getString(2)+" "+r.getString(3));}}return List.copyOf(out);});}
}
